<?php
require_once __DIR__ . '/../config/database.php'; require_once __DIR__ . '/../helpers/auth.php'; require_login(); require_once __DIR__ . '/../helpers/escape.php'; require_once __DIR__ . '/../helpers/csrf.php';
$pageTitle='Produk'; $message=''; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); if(($_POST['action']??'')==='add'){
 $sku=trim($_POST['sku']??'');$name=trim($_POST['name']??'');$category=(int)($_POST['category_id']??0);$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$minimum=filter_var($_POST['minimum_stock']??0,FILTER_VALIDATE_INT);
 if($sku===''||$name===''||$category<1||$price===false||$price<0||$minimum===false||$minimum<0){$error='Periksa kembali data produk. Harga dan batas stok tidak boleh negatif.';}
 else{try{$st=$pdo->prepare('INSERT INTO products(category_id,sku,name,price,stock,minimum_stock) VALUES(?,?,?,?,0,?)');$st->execute([$category,$sku,$name,$price,$minimum]);$message='Produk berhasil ditambahkan.';}catch(PDOException $e){$error='Produk gagal disimpan. SKU harus unik dan kategori harus valid.';}}
 } elseif(($_POST['action']??'')==='delete'){require_admin();$id=(int)$_POST['id'];try{$pdo->beginTransaction();$st=$pdo->prepare('SELECT COUNT(*) FROM stock_movements WHERE product_id=?');$st->execute([$id]);if((int)$st->fetchColumn()>0)throw new RuntimeException('Produk yang sudah memiliki histori transaksi tidak boleh dihapus.');$pdo->prepare('DELETE FROM product_suppliers WHERE product_id=?')->execute([$id]);$pdo->prepare('DELETE FROM products WHERE id=?')->execute([$id]);$pdo->commit();$message='Produk dihapus.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Produk tidak dapat dihapus.';}}
}
$categories=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();
$q=trim($_GET['q']??'');$cat=(int)($_GET['category_id']??0);$sort=$_GET['sort']??'name';$dir=strtoupper($_GET['dir']??'ASC');
$sortMap=['name'=>'p.name','price'=>'p.price','stock'=>'p.stock','sku'=>'p.sku'];if(!isset($sortMap[$sort]))$sort='name';if(!in_array($dir,['ASC','DESC'],true))$dir='ASC';
$where=[];$params=[];if($q!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}if($cat>0){$where[]='p.category_id=?';$params[]=$cat;}
$condition=$where?'WHERE '.implode(' AND ',$where):'';
$st=$pdo->prepare("SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id $condition ORDER BY {$sortMap[$sort]} $dir");$st->execute($params);$rows=$st->fetchAll();
require '_header.php';
?>
<h1>Data Produk</h1><?php if($message):?><div class="notice"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?>
<div class="card"><h2>Tambah Produk</h2><?php if(!$categories):?><p>Tambahkan kategori terlebih dahulu.</p><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="grid"><div><label>SKU</label><input name="sku" required maxlength="50"></div><div><label>Nama produk</label><input name="name" required maxlength="150"></div><div><label>Kategori</label><select name="category_id" required><?php foreach($categories as $c):?><option value="<?=e($c['id'])?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label>Harga (Rp)</label><input type="number" name="price" min="0" step="0.01" required></div><div><label>Batas stok rendah</label><input type="number" name="minimum_stock" min="0" value="5" required></div></div><div class="actions"><button>Tambah produk</button></div></form><?php endif;?></div>
<div class="card"><h2>Daftar Produk</h2><form method="get" class="inline"><div><label>Cari nama / SKU</label><input name="q" value="<?=e($q)?>"></div><div><label>Kategori</label><select name="category_id"><option value="0">Semua kategori</option><?php foreach($categories as $c):?><option value="<?=e($c['id'])?>" <?=$cat===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label>Urutkan</label><select name="sort"><?php foreach(['name'=>'Nama','sku'=>'SKU','price'=>'Harga','stock'=>'Stok'] as $k=>$v):?><option value="<?=$k?>" <?=$sort===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div><label>Arah</label><select name="dir"><option <?=$dir==='ASC'?'selected':''?>>ASC</option><option <?=$dir==='DESC'?'selected':''?>>DESC</option></select></div><div><button>Filter</button> <a class="btn secondary" href="products.php">Reset</a></div></form>
<div class="table-wrap" style="margin-top:16px"><table><tr><th>SKU</th><th>Produk</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Status</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['sku'])?></td><td><?=e($r['name'])?></td><td><?=e($r['category_name'])?></td><td>Rp <?=number_format($r['price'],0,',','.')?></td><td><?=e($r['stock'])?></td><td><?=$r['stock']<=$r['minimum_stock']?'<span class="pill">Stok rendah</span>':'Aman'?></td><td><?php if(($_SESSION['user']['role']??'')==='admin'):?><form method="post" onsubmit="return confirm('Hapus produk ini?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="danger">Hapus</button></form><?php else:?>-<?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">Data produk tidak ditemukan.</td></tr><?php endif;?></table></div></div>
<?php require '_footer.php';?>
